fn steer(d: int) {
  if speed > 0 { px = min(9, max(0, px + d)); }
}

every speed {
  if rise > 0 {
    ph += 1;
    rise -= 1;
  } else if solid(px, ph - 1) {
    rise = 3;
    ph += 1;
  } else {
    ph -= 1;
  }
  best = max(best, ph);
  if ph - base > 9 { base = ph - 9; }
  if ph < base {
    over = true;
    speed = 0;
  }
}

