fn onoff(on: bool) -> string {
  if on { return "on"; }
  return "off";
}

// Square i gets a character of the kind given.
fn put(i: int, kind: int) {
  kinds[i] = kind;
  if kind == 4 {
    chars[i] = letters[random(len(letters))];
  } else if kind == 2 {
    chars[i] = "" + random(10);
  } else {
    chars[i] = signs[random(len(signs))];
  }
}

// Square i gets any character of the kinds that are on, each as likely.
fn any(i: int) {
  let n = len(letters);
  if digits { n += 10; }
  if symbols { n += len(signs); }
  let r = random(n);
  if r < len(letters) {
    put(i, 4);
  } else if digits && r < len(letters) + 10 {
    put(i, 2);
  } else {
    put(i, 1);
  }
}

// Twelve characters, then one of each kind that is on in three different squares.
fn generate() {
  for i in 0..12 { any(i); }
  let a = random(12);
  let b = (a + 1 + random(11)) % 12;
  let c = random(12);
  for j in 0..2 {
    if c == a || c == b { c = (c + 1) % 12; }
  }
  put(a, 4);
  if digits { put(b, 2); }
  if symbols { put(c, 1); }
}

