// Dots and boxes against the computer: tap between two dots to draw a line; whoever closes a
// box wins it and plays again. The most boxes wins.
// icon: dot 5 5 2 dot 19 5 2 dot 5 19 2 dot 19 19 2 line 5 19 5 5 19 5 fill 8 8 16 8 16 16 8 16
// The board, 5 x 5 squares row by row: dots at even column and row, boxes at odd ones, lines
// between.
state drawn = [false; 25];
state owner = [0; 25];        // a box's: 0 none, 1 mine, 2 the computer's
state turn = 1;               // 1 me, 2 the computer
state got = false;            // the line drawn closed a box

fn at(c: int, r: int) -> int { return r * 5 + c; }

fn link(i: int) -> bool { return (i % 5 + i / 5) % 2 == 1; }

fn open(i: int) -> bool { return link(i) && !drawn[i]; }

fn left() -> int {
  let n = 0;
  for i in 0..25 {
    if open(i) { n += 1; }
  }
  return n;
}

fn boxes(p: int) -> int {
  let n = 0;
  for i in 0..25 {
    if owner[i] == p { n += 1; }
  }
  return n;
}

// Whether (c, r) is a box with k sides drawn.
fn has(c: int, r: int, k: int) -> bool {
  if c < 1 || c > 3 || r < 1 || r > 3 { return false; }
  let n = 0;
  if drawn[at(c, r - 1)] { n += 1; }
  if drawn[at(c, r + 1)] { n += 1; }
  if drawn[at(c - 1, r)] { n += 1; }
  if drawn[at(c + 1, r)] { n += 1; }
  return n == k;
}

// Whether a box beside line i has k sides drawn.
fn beside(i: int, k: int) -> bool {
  let c = i % 5;
  let r = i / 5;
  if r % 2 == 0 { return has(c, r - 1, k) || has(c, r + 1, k); }
  return has(c - 1, r, k) || has(c + 1, r, k);
}

// The computer's line: the first that closes a box, else the first giving no box a third side,
// else the first left.
fn pick() -> int {
  for i in 0..25 {
    if open(i) && beside(i, 3) { return i; }
  }
  for i in 0..25 {
    if open(i) && !beside(i, 2) { return i; }
  }
  for i in 0..25 {
    if open(i) { return i; }
  }
  return -1;
}

fn claim(c: int, r: int) {
  if has(c, r, 4) && owner[at(c, r)] == 0 {
    owner[at(c, r)] = turn;
    got = true;
  }
}

// Draws line i for whoever's turn it is; the turn passes unless it closed a box.
fn put(i: int) {
  drawn[i] = true;
  got = false;
  let c = i % 5;
  let r = i / 5;
  if r % 2 == 0 {
    claim(c, r - 1);
    claim(c, r + 1);
  } else {
    claim(c - 1, r);
    claim(c + 1, r);
  }
  if !got { turn = 3 - turn; }
}

fn tap(i: int) {
  if turn != 1 || !open(i) { return; }
  put(i);
  repeat 12 {
    if turn == 2 && left() > 0 { put(pick()); }
  }
}

