state filling = false;      // the tool: Fill, else the Pen

// Paints square i and every square joined to it by sides through its old color. Each square
// joins the list to visit as it is painted, so it is visited once.
fn fill(i: int) {
  let from = art[i];
  if from == pen { return; }
  let todo = [i];
  art[i] = pen;
  repeat 256 {
    if len(todo) > 0 {
      let k = todo[len(todo) - 1];
      remove(todo, len(todo) - 1);
      if k % 16 > 0 && art[k - 1] == from {
        art[k - 1] = pen;
        push(todo, k - 1);
      }
      if k % 16 < 15 && art[k + 1] == from {
        art[k + 1] = pen;
        push(todo, k + 1);
      }
      if k >= 16 && art[k - 16] == from {
        art[k - 16] = pen;
        push(todo, k - 16);
      }
      if k < 240 && art[k + 16] == from {
        art[k + 16] = pen;
        push(todo, k + 16);
      }
    }
  }
}

fn tap(c: int, r: int) {
  if c < 0 || c > 15 || r < 0 || r > 15 { return; }
  if filling { fill(r * 16 + c); } else { art[r * 16 + c] = pen; }
}

