// Mancala (Kalah) against the computer: the buttons 1 to 6 sow your pits, from the left.
// The last stone in your store plays again; in an empty pit of yours it takes the pit across.
// icon: loop 2 7 22 7 22 17 2 17 dot 7 12 2 dot 12 12 2 dot 17 12 2
state pits = [3, 3, 3, 3, 3, 3, 0, 3, 3, 3, 3, 3, 3, 0];
                          // 0-5 my row left to right, 6 my store, 7-12 its row right to left,
                          // 13 its store: the way the stones go round
state again = false;      // whether the last stone sown fell in the mover's store
state over = false;

fn home(p: int) -> int { return 6 + p * 7; }

// The stones in p's row: 0 mine, 1 the computer's.
fn side(p: int) -> int {
  let n = 0;
  for k in 0..6 { n += pits[p * 7 + k]; }
  return n;
}

// Its pit nearest its store that holds stones: the leftmost of the top row.
fn pick() -> int {
  for k in 0..6 {
    if pits[12 - k] > 0 { return 12 - k; }
  }
  return 7;
}

// Pit i's stones, one into each pit on, skipping the other's store; then a capture.
fn sow(i: int, p: int) {
  let n = pits[i];
  pits[i] = 0;
  let j = i;
  for k in 0..n {
    j = (j + 1) % 14;
    if j == home(1 - p) { j = (j + 1) % 14; }
    pits[j] += 1;
  }
  again = j == home(p);
  if j / 7 == p && j != home(p) && pits[j] == 1 && pits[12 - j] > 0 {
    pits[home(p)] += pits[12 - j] + 1;
    pits[12 - j] = 0;
    pits[j] = 0;
  }
}

// A row empty ends the game: each row's stones go to its owner's store.
fn finish() {
  if side(0) > 0 && side(1) > 0 { return; }
  for k in 0..6 {
    pits[6] += pits[k];
    pits[k] = 0;
    pits[13] += pits[7 + k];
    pits[7 + k] = 0;
  }
  over = true;
}

// The computer's turn, at once, and again while its last stone falls in its store.
fn reply() {
  let going = true;
  repeat 36 {
    if going {
      sow(pick(), 1);
      finish();
      going = !over && again;
    }
  }
}

fn play(i: int) {
  if over || pits[i] == 0 { return; }
  sow(i, 0);
  finish();
  if !over && !again { reply(); }
}

fn fresh() {
  for k in 0..14 { pits[k] = 3; }
  pits[6] = 0;
  pits[13] = 0;
  again = false;
  over = false;
}

