// Gomoku for two: tap an empty square to place a stone, Blue first, then Red. Exactly five in a
// row wins (across, down or diagonally); six or more do not.
// icon: line 2 8 22 8 line 2 16 22 16 line 8 2 8 22 line 16 2 16 22 dot 8 8 3 ring 16 16 3
state board = [0; 225];   // row by row from the top: 0 empty, 1 Blue, 2 Red
state turn = 1;
state result = 0;         // 0 playing, 1 Blue won, 2 Red won, 3 a draw

fn at(c: int, r: int) -> int {
  if c < 0 || c >= 15 || r < 0 || r >= 15 { return 0; }
  return board[r * 15 + c];
}

// How many of p's stones run on from (c, r), a step (dc, dr) at a time.
fn run(c: int, r: int, dc: int, dr: int, p: int) -> int {
  let n = 0;
  for k in 1..15 {
    if n == k - 1 && at(c + dc * k, r + dr * k) == p { n = k; }
  }
  return n;
}

// Whether p's stone at (c, r) lies in a line of exactly five, one way or another.
fn five(c: int, r: int, p: int) -> bool {
  if run(c, r, 1, 0, p) + run(c, r, -1, 0, p) == 4 { return true; }
  if run(c, r, 0, 1, p) + run(c, r, 0, -1, p) == 4 { return true; }
  if run(c, r, 1, 1, p) + run(c, r, -1, -1, p) == 4 { return true; }
  return run(c, r, 1, -1, p) + run(c, r, -1, 1, p) == 4;
}

fn full() -> bool {
  for i in 0..225 {
    if board[i] == 0 { return false; }
  }
  return true;
}

fn tap(i: int) {
  if result != 0 || board[i] != 0 { return; }
  board[i] = turn;
  if five(i % 15, i / 15, turn) {
    result = turn;
  } else if full() {
    result = 3;
  } else {
    turn = 3 - turn;
  }
}

fn tint(v: int) -> int {
  if v == 1 { return 4; }
  return 1;
}

// Wooden squares 10 units apart, each stone a circle in its color.
fn scene() {
  for i in 0..225 {
    let px = (i % 15) * 10;
    let py = (i / 15) * 10;
    rect(px, py, 9, 9, 3);
    if board[i] != 0 { circle(px + 4, py + 4, 4, tint(board[i])); }
  }
}

fn status() -> string {
  if result == 1 { return "Blue wins"; }
  if result == 2 { return "Red wins"; }
  if result == 3 { return "Draw"; }
  if turn == 1 { return "Blue to play"; }
  return "Red to play";
}

