// Blackjack: Deal, then Hit for cards or Stand; the dealer draws to 17. Beat its total without
// going over 21. Each round bets 10 chips; a blackjack pays 15. The deck comes in a fixed order.
// icon: loop 3 5 13 5 13 19 3 19 fill 10 8 20 8 20 22 10 22
state deck = ["10", "9", "6", "7", "3", "8", "A", "10", "6", "8", "9", "4", "10", "A", "K", "Q",
  "A", "9", "K", "9", "9", "10", "7", "7", "Q", "10", "6", "8", "A", "2", "5", "3", "2", "A",
  "A", "3", "7", "8", "K", "8", "6", "A"];
state next = 0;           // the deck's next card
state mine = [0; 0];      // my cards, as places in the deck
state theirs = [0; 0];    // the dealer's
state hidden = false;     // whether the dealer's second card is face down
state playing = false;    // whether it is my turn
state chips = 100;
state news = "";

fn worth(k: int) -> int {
  let s = deck[k];
  if s == "A" { return 1; }
  if s == "J" || s == "Q" || s == "K" { return 10; }
  return parse(s, 0);
}

fn card(who: int, k: int) -> int {
  if who == 0 { return mine[k]; }
  return theirs[k];
}

// The best total of the first n cards of who (0 me, 1 the dealer): an ace is 11 if that stays
// at 21 or under.
fn total(who: int, n: int) -> int {
  let t = 0;
  let ace = false;
  for k in 0..n {
    t += worth(card(who, k));
    if deck[card(who, k)] == "A" { ace = true; }
  }
  if ace && t + 10 <= 21 { return t + 10; }
  return t;
}

fn hand() -> int { return total(0, len(mine)); }

// The dealer's total of the cards face up.
fn shown() -> int {
  if hidden { return total(1, 1); }
  return total(1, len(theirs));
}

fn give(who: int) {
  if who == 0 { push(mine, next); } else { push(theirs, next); }
  next = (next + 1) % len(deck);
}

fn end(won: int, say: string) {
  chips += won;
  news = say;
  hidden = false;
  playing = false;
}

fn deal() {
  clear(mine);
  clear(theirs);
  give(0);
  give(1);
  give(0);
  give(1);
  hidden = true;
  playing = true;
  news = "";
  let me = total(0, 2) == 21;
  let it = total(1, 2) == 21;
  if me && it { end(0, "Push"); } else if me { end(15, "Blackjack! You win"); } else if it { end(-10, "Dealer blackjack: you lose"); }
}

fn hit() {
  give(0);
  if hand() > 21 { end(-10, "Bust: you lose"); }
}

fn stand() {
  hidden = false;
  repeat 20 {
    if total(1, len(theirs)) < 17 { give(1); }
  }
  let it = total(1, len(theirs));
  if it > 21 || hand() > it { end(10, "You win"); } else if hand() < it { end(-10, "You lose"); } else { end(0, "Push"); }
}

// A card at x, y: its rank on a light face, or the blue back when face down.
fn face(k: int, x: int, y: int, down: bool) {
  if down {
    rect(x, y, 18, 26, 4);
  } else {
    rect(x, y, 18, 26, 7);
    text(deck[k], x + 9, y + 13, 10, 9);
  }
}

