// Blackjack with bets: set the bet with +10 and -10, Deal, then Hit, Stand or Double (one card at
// twice the stake). The dealer hits a soft 17. A blackjack pays one and a half times the bet.
// icon: loop 2 4 12 4 12 18 2 18 loop 12 6 22 6 22 20 12 20 line 17 10 17 16 line 14 13 20 13
state deck = ["5", "10", "6", "7", "10", "10", "6", "7", "A", "4", "A", "9", "Q", "8", "9", "5",
  "2", "10", "3", "K", "6", "10", "4", "9", "5", "10", "A", "9", "6", "10"];
state next = 0;           // the deck's next card
state mine = [0; 0];      // my cards, as places in the deck
state theirs = [0; 0];    // the dealer's
state hidden = false;     // whether the dealer's second card is face down
state playing = false;    // whether it is my turn
state chips = 100;
state bet = 10;
state stake = 10;         // this round's bet, twice it once doubled
state news = "";

fn worth(k: int) -> int {
  let s = deck[k];
  if s == "A" { return 1; }
  if s == "J" || s == "Q" || s == "K" { return 10; }
  return parse(s, 0);
}

fn card(who: int, k: int) -> int {
  if who == 0 { return mine[k]; }
  return theirs[k];
}

// The total of who's first n cards (0 me, 1 the dealer), every ace counted as 1.
fn hard(who: int, n: int) -> int {
  let t = 0;
  for k in 0..n { t += worth(card(who, k)); }
  return t;
}

fn ace(who: int, n: int) -> bool {
  for k in 0..n {
    if deck[card(who, k)] == "A" { return true; }
  }
  return false;
}

// The best total: an ace is 11 if that stays at 21 or under.
fn total(who: int, n: int) -> int {
  if ace(who, n) && hard(who, n) + 10 <= 21 { return hard(who, n) + 10; }
  return hard(who, n);
}

fn hand() -> int { return total(0, len(mine)); }

// The dealer's total of the cards face up.
fn shown() -> int {
  if hidden { return total(1, 1); }
  return total(1, len(theirs));
}

// Whether the dealer draws: under 17, or a soft 17 (an ace counted as 11).
fn draws() -> bool {
  let n = len(theirs);
  if total(1, n) < 17 { return true; }
  return total(1, n) == 17 && hard(1, n) == 7;
}

fn give(who: int) {
  if who == 0 { push(mine, next); } else { push(theirs, next); }
  next = (next + 1) % len(deck);
}

fn end(won: int, say: string) {
  chips += won;
  news = say;
  hidden = false;
  playing = false;
}

fn deal() {
  clear(mine);
  clear(theirs);
  give(0);
  give(1);
  give(0);
  give(1);
  stake = bet;
  hidden = true;
  playing = true;
  news = "";
  let me = total(0, 2) == 21;
  let it = total(1, 2) == 21;
  if me && it {
    end(0, "Push");
  } else if me {
    end(stake * 3 / 2, "Blackjack! You win");
  } else if it {
    end(-stake, "Dealer blackjack: you lose");
  }
}

fn hit() {
  give(0);
  if hand() > 21 { end(-stake, "Bust: you lose"); }
}

fn stand() {
  hidden = false;
  repeat 20 {
    if draws() { give(1); }
  }
  let it = total(1, len(theirs));
  if it > 21 || hand() > it {
    end(stake, "You win");
  } else if hand() < it {
    end(-stake, "You lose");
  } else {
    end(0, "Push");
  }
}

fn double() {
  stake = stake * 2;
  hit();
  if playing { stand(); }
}

// A card at x, y: its rank on a light face, or the red back when face down.
fn face(k: int, x: int, y: int, down: bool) {
  if down {
    rect(x, y, 18, 26, 1);
  } else {
    rect(x, y, 18, 26, 7);
    text(deck[k], x + 9, y + 13, 10, 9);
  }
}

