// Pac-Man: the arrows (or a tap beside Pac-Man) point the way it goes; eat every dot; the red
// ghost chases you, and meeting it costs one of 3 lives.
// icon: fill 11 12 18 17 14 20 8 20 3 16 2 10 5 5 11 3 18 7 dot 20 12 2
state dots = [false; 49];       // whether square c + 7 * r holds a dot
state px = 3;                   // Pac-Man's square, and the way it points
state py = 6;
state dx = 0;
state dy = 0;
state gx = 3;                   // the ghost's square
state gy = 0;
state steps = 0;                // steps since Start
state score = 0;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state won = false;
state over = false;

fn wall(c: int, r: int) -> bool { return c % 2 == 1 && r % 2 == 1; }

fn free(c: int, r: int) -> bool { return c >= 0 && c < 7 && r >= 0 && r < 7 && !wall(c, r); }

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

fn left() -> int {
  let n = 0;
  for i in 0..49 {
    if dots[i] { n += 1; }
  }
  return n;
}

// Both back at their starts, Pac-Man still.
fn home() {
  px = 3;
  py = 6;
  dx = 0;
  dy = 0;
  gx = 3;
  gy = 0;
}

fn start() {
  for i in 0..49 { dots[i] = !wall(i % 7, i / 7) && i != 45; }
  home();
  steps = 0;
  score = 0;
  lives = 3;
  won = false;
  over = false;
  speed = 200;
}

// Pac-Man and the ghost on one square: a life lost, and both back at their starts.
fn meet() {
  if px == gx && py == gy {
    lives -= 1;
    home();
    if lives == 0 {
      over = true;
      speed = 0;
    }
  }
}

// The ghost a square toward Pac-Man: across if it can, else up or down.
fn chase() {
  let sx = sign(px - gx);
  let sy = sign(py - gy);
  if sx != 0 && free(gx + sx, gy) {
    gx += sx;
  } else if sy != 0 && free(gx, gy + sy) {
    gy += sy;
  }
  meet();
}

fn point(x: int, y: int) {
  if speed > 0 {
    dx = x;
    dy = y;
  }
}

every speed {
  steps += 1;
  if free(px + dx, py + dy) {
    px += dx;
    py += dy;
