fn hill(c: int) -> bool { return c >= 4 && c <= 6; }

fn pad(c: int) -> bool { return c >= 8 && c <= 10; }

// A round from the top: height 80, column 1, still.
fn begin() {
  height = 80;
  speed = 0;
  lx = 1;
  drift = 0;
}

fn start() {
  fuel = 30;
