}

// A side jet: d is -1 for left, 1 for right.
fn jet(d: int) {
  if step > 0 && fuel > 0 && drift != d {
    drift += d;
    fuel -= 1;
  }
}

// This round is over: the next begins, or after the third the game ends.
fn next() {
  if round == 3 {
    over = true;
    step = 0;
  } else {
    round += 1;
    begin();
  }
}

