// Pool: tap a square to shoot the cue ball toward it (- and + set the power); a ball it meets
// rolls on in its place. Pot all three reds in as few shots as you can.
// icon: ring 12 12 9 dot 9 10 3 dot 15 14 3
state bx = [2, 4, 5, 9];        // the balls, the cue ball first: square, and whether on the table
state by = [2, 4, 5, 3];
state on = [true, true, true, true];
state mover = -1;               // the ball rolling (-1: none), its way and the squares left
state dx = 0;
state dy = 0;
state left = 0;
state power = 5;
state shots = 0;
state potted = 0;
state speed = 0;                // 100 while a game runs, else 0
state done = false;

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

fn pocket(c: int, r: int) -> bool { return (c == 0 || c == 6 || c == 12) && (r == 0 || r == 6); }

// The ball on square (c, r), or -1.
fn at(c: int, r: int) -> int {
  for i in 0..4 {
    if on[i] && bx[i] == c && by[i] == r { return i; }
  }
  return -1;
}

fn start() {
  bx = [2, 4, 5, 9];
  by = [2, 4, 5, 3];
  on = [true, true, true, true];
  mover = -1;
  power = 5;
  shots = 0;
  potted = 0;
  done = false;
  speed = 100;
}

fn shoot(c: int, r: int) {
  if speed > 0 && mover < 0 && (c != bx[0] || r != by[0]) {
    dx = sign(c - bx[0]);
    dy = sign(r - by[0]);
    left = power;
    mover = 0;
    shots += 1;
  }
}

// A ball in a pocket: a red is potted, the cue ball comes back with a shot added.
fn drop(i: int) {
  mover = -1;
  if i == 0 {
    bx[0] = 2;
    by[0] = 2;
    shots += 1;
  } else {
    on[i] = false;
    potted += 1;
    if potted == 3 {
      done = true;
      speed = 0;
    }
  }
}

every speed {
  if mover >= 0 {
    let i = mover;
    if bx[i] + dx < 0 || bx[i] + dx > 12 { dx = -dx; }
    if by[i] + dy < 0 || by[i] + dy > 6 { dy = -dy; }
    let j = at(bx[i] + dx, by[i] + dy);
    if j >= 0 {
      mover = j;
    } else {
      bx[i] += dx;
      by[i] += dy;
      left -= 1;
      if pocket(bx[i], by[i]) {
        drop(i);
      } else if left == 0 {
        mover = -1;
      }
    }
  }
}

fn scene() {
  let cells = [-1; 91];
  for i in 0..91 {
    if pocket(i % 13, i / 13) { cells[i] = 8; }
  }
  for i in 1..4 {
    if on[i] { cells[by[i] * 13 + bx[i]] = 1; }
  }
  cells[by[0] * 13 + bx[0]] = 3;
  pixels(cells, 0, 0, 13, 10);
  if done { text("Cleared", 65, 35, 14, 11); }
}

