// Bomberman: the arrows move (or tap beside you), space or Bomb drops a bomb (two at most); a
// blast sets off the bombs it reaches. The red enemy chases you, faster after the first kill.
// icon: dot 11 14 7 line 15 8 18 4 line 18 4 21 3 dot 21 3 1
state px = 0;                   // the player's square
state py = 0;
state ex = 6;                   // the enemy's square
state ey = 6;
state bombs = [0; 0];           // the bombs down: square, and steps until each blows
state fuses = [0; 0];
state blast = [false; 49];      // the blast, shown until the next step
state steps = 0;
state lives = 3;
state kills = 0;
state speed = 0;                // ms a step; 0 while no game runs
state won = false;
state over = false;

fn pillar(c: int, r: int) -> bool { return c % 2 == 1 && r % 2 == 1; }

fn bombat(i: int) -> int {
  for k in 0..len(bombs) {
    if bombs[k] == i { return k; }
  }
  return -1;
}

fn free(c: int, r: int) -> bool {
  return c >= 0 && c < 7 && r >= 0 && r < 7 && !pillar(c, r) && bombat(r * 7 + c) < 0;
}

fn sign(n: int) -> int {
  if n > 0 { return 1; }
  if n < 0 { return -1; }
  return 0;
}

fn start() {
  px = 0;
  py = 0;
  ex = 6;
  ey = 6;
  clear(bombs);
  clear(fuses);
  for i in 0..49 { blast[i] = false; }
  steps = 0;
  lives = 3;
  kills = 0;
  won = false;
  over = false;
  speed = 200;
}

fn die() {
  lives -= 1;
  px = 0;
  py = 0;
  ex = 6;
  ey = 6;
  if lives == 0 {
    over = true;
    speed = 0;
  }
}

fn touch() {
  if speed > 0 && px == ex && py == ey { die(); }
}

// The blast of bomb k on its square and the 4 next to it; a bomb it covers blows at once.
fn cover(c: int, r: int) {
  if c >= 0 && c < 7 && r >= 0 && r < 7 && !pillar(c, r) {
    blast[r * 7 + c] = true;
    let k = bombat(r * 7 + c);
    if k >= 0 { fuses[k] = 0; }
  }
}

// Blows every bomb whose fuse is out, again while the blasts set off more (5 rounds at most).
fn blasts() {
  repeat 3 {
    let k = 0;
    for n in 0..len(bombs) {
      if k < len(bombs) && fuses[k] <= 0 {
        let c = bombs[k] % 7;
        let r = bombs[k] / 7;
        remove(bombs, k);
        remove(fuses, k);
        cover(c, r);
        cover(c + 1, r);
        cover(c - 1, r);
        cover(c, r + 1);
        cover(c, r - 1);
      } else {
        k += 1;
      }
    }
  }
}

every speed {
  steps += 1;
  for i in 0..49 { blast[i] = false; }
  for k in 0..len(fuses) { fuses[k] -= 1; }
  blasts();
  if blast[ey * 7 + ex] {
    kills += 1;
    ex = 6;
    ey = 6;
    if kills == 3 {
      won = true;
      speed = 0;
    }
  }
  if speed > 0 && blast[py * 7 + px] { die(); }
  if speed > 0 && (kills > 0 || steps % 2 == 0) {
    let sx = sign(px - ex);
    let sy = sign(py - ey);
    if sx != 0 && free(ex + sx, ey) {
      ex += sx;
    } else if sy != 0 && free(ex, ey + sy) {
      ey += sy;
    }
    touch();
  }
}

fn walk(dx: int, dy: int) {
  if speed > 0 && free(px + dx, py + dy) {
    px += dx;
    py += dy;
    touch();
  }
}

fn drop() {
  if speed > 0 && len(bombs) < 2 && bombat(py * 7 + px) < 0 {
    push(bombs, py * 7 + px);
    push(fuses, 6);
  }
}

