// Racing: left and right (or a tap beside your car) change lanes; dodge the red cars coming
// down. Each 5 passed speeds the road up; 12 passed wins; 3 crashes end it.
// icon: fill 8 4 16 4 17 20 7 20 fill 5 7 7 7 7 11 5 11 fill 17 7 19 7 19 11 17 11 fill 5 14 7 14 7 18 5 18
state cx = [0; 0];              // the cars: lane (column) and row
state cy = [0; 0];
