state steps = 0;
state made = 0;                 // cars that have come in this game
state score = 0;
state lives = 3;
state speed = 0;                // ms a step; 0 while no game runs
state won = false;
state over = false;

fn level() -> int { return 1 + score / 5; }

fn pace() -> int { return max(200, 350 - 50 * level()); }

fn start() {
  clear(cx);
  clear(cy);
  lane = 3;
  steps = 0;
  made = 0;
  score = 0;
  lives = 3;
  won = false;
  over = false;
  speed = pace();
}

// A crash: a life lost, the road cleared, my car back in lane 3.
fn crash() {
  lives -= 1;
  clear(cx);
  clear(cy);
  lane = 3;
  if lives == 0 {
    over = true;
    speed = 0;
  }
}

fn hit() -> bool {
  for i in 0..len(cx) {
    if cx[i] == lane && cy[i] == 10 { return true; }
  }
  return false;
}

fn steer(d: int) {
  if speed > 0 && lane + d >= 1 && lane + d <= 5 {
    lane += d;
    if hit() { crash(); }
  }
}

every speed {
  steps += 1;
  for i in 0..len(cy) { cy[i] += 1; }
  if len(cy) > 0 && cy[0] > 11 {
    remove(cx, 0);
    remove(cy, 0);
    score += 1;
  }
  if score >= 12 {
    won = true;
    speed = 0;
  } else {
    if hit() { crash(); }
    if speed > 0 {
      if steps % 3 == 0 {
        push(cx, lanes[made % 5]);
        push(cy, 0);
        made += 1;
      }
      speed = pace();
    }
  }
}

