// Square i of the track, clockwise around the edge from column 0, row 0.
fn tx(i: int) -> int {
  if i <= 7 { return i; }
  if i <= 12 { return 7; }
  if i <= 19 { return 19 - i; }
  return 0;
}

fn ty(i: int) -> int {
  if i <= 7 { return 0; }
  if i <= 12 { return i - 7; }
  if i <= 19 { return 5; }
  return 24 - i;
}

fn corner(i: int) -> bool { return i == 0 || i == 7 || i == 12 || i == 19; }

fn start() {
  me = 0;
  speed = 0;
  rival = 0;
  laps = 0;
  rlaps = 0;
  result = "";
  step = 250;
}

fn gear(d: int) {
  if step > 0 { speed = min(3, max(0, speed + d)); }
}

every step {
  let n = speed;
  for k in 0..n {
    if speed > 0 {
      me = (me + 1) % 24;
      if me == 0 { laps += 1; }
      if n == 3 && corner(me) { speed = 0; }
    }
  }
  if laps == 2 {
    result = "You win";
    step = 0;
  } else {
    rival = (rival + 2) % 24;
    if rival < 2 { rlaps += 1; }
    if rlaps == 2 {
      result = "You lose";
      step = 0;
    }
  }
}

on key "up" { gear(1); }
on key "down" { gear(-1); }

