  for i in 0..24 {
    if corner(i) { cells[ty(i) * 8 + tx(i)] = 3; }
  }
  if step > 0 || result != "" {
    cells[ty(rival) * 8 + tx(rival)] = 1;
    cells[ty(me) * 8 + tx(me)] = 4;
  }
  pixels(cells, 0, 0, 8, 10);
  if result != "" { text(result, 40, 30, 10, 9); }
}

