// Rush hour by taps: tap a car, then tap an empty square in its line to slide it there. Get the
// red car out on the right; Undo takes a move back, Reset starts over.
// icon: fill 3 15 5 9 9 6 15 6 19 9 21 15 dot 8 16 3 dot 16 16 3
// The cars, the red one first: the left or top square of each, whether it lies across, its length.
state cx = [0, 0, 3, 3, 5, 0, 1, 3, 4];
state cy = [2, 0, 0, 1, 2, 3, 4, 4, 5];
state across = [true, false, true, false, false, false, true, false, true];
state size = [2, 2, 3, 2, 3, 2, 2, 2, 2];
state picked = -1;
state moves = 0;
state won = false;
state hk = [0; 0];            // the moves made, to undo: the car and where it was
state hc = [0; 0];
state hr = [0; 0];

fn wall(c: int, r: int) -> bool { return c == 2 && r == 3; }

fn covers(k: int, c: int, r: int) -> bool {
  if across[k] { return r == cy[k] && c >= cx[k] && c < cx[k] + size[k]; }
  return c == cx[k] && r >= cy[k] && r < cy[k] + size[k];
}

// The car on square (c, r), else -1.
fn owner(c: int, r: int) -> int {
  for k in 0..len(cx) {
    if covers(k, c, r) { return k; }
  }
  return -1;
}

fn empty(c: int, r: int) -> bool { return !wall(c, r) && owner(c, r) < 0; }

// Whether every square from (c, r) on by (dc, dr), n of them, is empty.
fn clear_way(c: int, r: int, dc: int, dr: int, n: int) -> bool {
  for i in 0..n {
    if !empty(c + dc * i, r + dr * i) { return false; }
  }
  return true;
}

// The picked car slid so that its nearer end lands on the empty square (c, r), if the way is free.
fn slide(c: int, r: int) {
  let k = picked;
  if k < 0 { return; }
  let nc = cx[k];
  let nr = cy[k];
  if across[k] && r == cy[k] && c < cx[k] && clear_way(c, r, 1, 0, cx[k] - c) { nc = c; }
  if across[k] && r == cy[k] && c >= cx[k] + size[k] && clear_way(c, r, -1, 0, c - cx[k] - size[k] + 1) { nc = c - size[k] + 1; }
  if !across[k] && c == cx[k] && r < cy[k] && clear_way(c, r, 0, 1, cy[k] - r) { nr = r; }
  if !across[k] && c == cx[k] && r >= cy[k] + size[k] && clear_way(c, r, 0, -1, r - cy[k] - size[k] + 1) { nr = r - size[k] + 1; }
  if nc == cx[k] && nr == cy[k] { return; }
  push(hk, k);
  push(hc, cx[k]);
  push(hr, cy[k]);
  cx[k] = nc;
  cy[k] = nr;
  moves += 1;
  if cx[0] == 4 { won = true; }
}

fn tap(c: int, r: int) {
  if won { return; }
  if owner(c, r) >= 0 { picked = owner(c, r); } else if !wall(c, r) { slide(c, r); }
}

fn undo() {
  let n = len(hk);
  if won || n == 0 { return; }
  cx[hk[n - 1]] = hc[n - 1];
  cy[hk[n - 1]] = hr[n - 1];
  remove(hk, n - 1);
  remove(hc, n - 1);
  remove(hr, n - 1);
  moves -= 1;
}

fn reset() {
  cx = [0, 0, 3, 3, 5, 0, 1, 3, 4];
  cy = [2, 0, 0, 1, 2, 3, 4, 4, 5];
  clear(hk);
  clear(hc);
  clear(hr);
  picked = -1;
  moves = 0;
  won = false;
}

fn tint(k: int) -> int {
  if k == 0 { return 1; }
  if size[k] == 3 { return 5; }
  return 4;
}

// Squares of 20 units: the wall, the cars in their colors, the picked one outlined, the exit.
fn scene() {
  let b = [-1; 36];
  b[20] = 8;
  for k in 0..len(cx) {
    for i in 0..size[k] {
      if across[k] { b[cy[k] * 6 + cx[k] + i] = tint(k); } else { b[(cy[k] + i) * 6 + cx[k]] = tint(k); }
    }
  }
  pixels(b, 0, 0, 6, 20);
  rect(118, 40, 2, 20, 11);
  if picked >= 0 {
    let w = 20;
    let h = 20;
    if across[picked] { w = size[picked] * 20; } else { h = size[picked] * 20; }
    let x = cx[picked] * 20;
    let y = cy[picked] * 20;
    line(x + 1, y + 1, x + w - 1, y + 1, 2, 9);
    line(x + 1, y + h - 1, x + w - 1, y + h - 1, 2, 9);
    line(x + 1, y + 1, x + 1, y + h - 1, 2, 9);
    line(x + w - 1, y + 1, x + w - 1, y + h - 1, 2, 9);
  }
  if won { text("Solved", 60, 60, 16, 9); }
}

