// Finds the top left square's area: its color's squares joined to it, pass by pass.
fn find() {
  area = [false; 49];
  area[0] = true;
  size = 1;
  repeat 49 {
    for i in 0..49 {
      if !area[i] && board[i] == board[0] {
        let c = i % 7;
        if (c > 0 && area[i - 1]) || (c < 6 && area[i + 1]) || (i >= 7 && area[i - 7]) || (i < 42 && area[i + 7]) {
