  for i in 0..81 {
    let x = 10 + (i % 9) * 20;
    let y = 10 + (i / 9) * 20;
    if board[i] == 1 { circle(x, y, 9, 9); }
    if board[i] == 2 {
      circle(x, y, 9, 7);
      ring(x, y, 9, 1, 10);
    }
  }
}

fn status() -> string {
  if !over {
    if turn == 1 { return "Black to play"; }
    return "White to play";
  }
  let b = area(1);
  let w = area(2) + 7;
  let say = "Draw";
  if b > w { say = "Black wins"; }
  if w > b { say = "White wins"; }
  return "Black " + b + " White " + w + ": " + say;
}

