// Backgammon for two, the dice from a fixed list: tap a point of yours to pick it, then a die to
// move a checker from it that far; from the bar a die enters. White goes from 24 to 1, Black back.
// icon: line 3 4 6 20 9 4 line 9 4 12 20 15 4 line 15 4 18 20 21 4 dot 6 9 2 dot 18 9 2
state pos = [0, -2, 0, 0, 0, 0, 5, 0, 3, 0, 0, 0, -5, 5, 0, 0, 0, -3, 0, -5, 0, 0, 0, 0, 2, 0];
                          // points 1 to 24: white checkers above 0, black below
state bar = [0, 0, 0];    // on the bar: white at 1, black at 2
state off = [0, 0, 0];    // borne off
state rolls = [3, 1, 6, 4, 1, 2, 5, 5, 6, 6, 3, 2, 4, 1, 6, 5];
state next = 2;           // the list's next number
state dice = [3, 1];      // the dice left to play
state turn = 1;           // 1 white, 2 black
state pick = -1;          // the point picked
state winner = 0;

fn sign(t: int) -> int {
  if t == 1 { return 1; }
  return -1;
}

fn own(p: int, t: int) -> bool { return pos[p] * sign(t) > 0; }

// Whether t's checkers are all home: none on the bar, white's on 1 to 6, black's on 19 to 24.
fn home(t: int) -> bool {
  if bar[t] > 0 { return false; }
  for p in 1..25 {
    if own(p, t) && ((t == 1 && p > 6) || (t == 2 && p < 19)) { return false; }
  }
  return true;
}

// Where a checker of t from point src (0: the bar) lands with die d: a point, 0 off the board,
// -1 if it may not go.
fn dest(src: int, d: int, t: int) -> int {
  let q = src - d;
  if src == 0 { q = 25 - d; }
  if t == 2 {
    q = src + d;
    if src == 0 { q = d; }
  }
  if src > 0 && !own(src, t) { return -1; }
  if q >= 1 && q <= 24 {
    if pos[q] * sign(t) >= -1 { return q; }
    return -1;
  }
  if !home(t) { return -1; }
  let dist = src;
  if t == 2 { dist = 25 - src; }
  if d == dist { return 0; }
  for p in 1..25 {
    if own(p, t) && ((t == 1 && p > src) || (t == 2 && p < src)) { return -1; }
  }
  return 0;
}

// Whether the player to play can use a die left.
fn able() -> bool {
  for k in 0..len(dice) {
    if bar[turn] > 0 && dest(0, dice[k], turn) >= 0 { return true; }
    for p in 1..25 {
      if bar[turn] == 0 && dest(p, dice[k], turn) >= 0 { return true; }
    }
  }
  return false;
}

fn roll() {
  let a = rolls[next];
  let b = rolls[(next + 1) % len(rolls)];
  next = (next + 2) % len(rolls);
  clear(dice);
  push(dice, a);
  push(dice, b);
  if a == b {
    push(dice, a);
    push(dice, a);
  }
}

// The turn passes, with the next roll, while the dice are used up or none can be used.
fn settle() {
  repeat 30 {
    if winner == 0 && (len(dice) == 0 || !able()) {
      turn = 3 - turn;
      pick = -1;
      roll();
    }
  }
}

// Die d: a checker from the bar, else from the picked point, moves that far; one alone where it
// lands is hit.
fn use(d: int) {
  let k = -1;
  for j in 0..len(dice) {
    if dice[j] == d && k < 0 { k = j; }
  }
  let src = pick;
  if bar[turn] > 0 { src = 0; }
  if winner != 0 || k < 0 || src < 0 { return; }
  let q = dest(src, d, turn);
  if q < 0 { return; }
  let s = sign(turn);
  if src == 0 { bar[turn] -= 1; } else { pos[src] -= s; }
  if q == 0 { off[turn] += 1; }
  if q > 0 && pos[q] == -s {
    pos[q] = 0;
    bar[3 - turn] += 1;
  }
  if q > 0 { pos[q] += s; }
  remove(dice, k);
  pick = -1;
  if off[turn] == 15 { winner = turn; } else { settle(); }
}

fn tap(p: int) {
  if winner == 0 && own(p, turn) { pick = p; }
}

fn pips(t: int) -> int {
  let n = bar[t] * 25;
  for p in 1..25 {
    if own(p, t) && t == 1 { n += pos[p] * p; }
    if own(p, t) && t == 2 { n -= pos[p] * (25 - p); }
  }
  return n;
}

fn fresh() {
  let start = [0, -2, 0, 0, 0, 0, 5, 0, 3, 0, 0, 0, -5, 5, 0, 0, 0, -3, 0, -5, 0, 0, 0, 0, 2, 0];
  for p in 0..26 { pos[p] = start[p]; }
  for t in 0..3 {
    bar[t] = 0;
    off[t] = 0;
  }
  next = 0;
  turn = 1;
  pick = -1;
  winner = 0;
  roll();
}

// The 12 x 2 board: points 13 to 24 along the top, 12 to 1 along the bottom, left to right.
fn column(p: int) -> int {
  if p >= 13 { return p - 13; }
  return 12 - p;
}

fn point(c: int, r: int) -> int {
  if r == 0 { return 13 + c; }
  return 12 - c;
}

// Each point a strip 20 units wide, its checkers stacked from the edge (white silver, black ink),
// five at most drawn and the rest counted; the picked point lit.
fn scene() {
  for p in 1..25 {
    let x = column(p) * 20;
    let top = p >= 13;
    let tint = 8;
    if p == pick { tint = 11; }
    if top { rect(x + 2, 0, 16, 36, tint); } else { rect(x + 2, 44, 16, 36, tint); }
    let n = abs(pos[p]);
    let c = 7;
    if pos[p] < 0 { c = 9; }
    for k in 0..min(n, 5) {
      let y = 76 - k * 8;
      if top { y = 4 + k * 8; }
      circle(x + 10, y, 4, c);
    }
    if n > 5 && top { text(n, x + 10, 36, 6, 11); }
    if n > 5 && !top { text(n, x + 10, 44, 6, 11); }
  }
}

fn status() -> string {
  if winner == 1 { return "White wins"; }
  if winner == 2 { return "Black wins"; }
  if turn == 1 { return "White to play"; }
  return "Black to play";
}

