    let x = column(p) * 20;
    let top = p >= 13;
    let tint = 8;
    if p == pick { tint = 11; }
    if top { rect(x + 2, 0, 16, 36, tint); } else { rect(x + 2, 44, 16, 36, tint); }
    let n = abs(pos[p]);
