// Tank Battle: the arrows (or a tap) drive your blue tank, space or Fire shoots the way it
// faces; the red computer tank hunts you. Walls stop tanks and shells; first to 3 hits wins.
// icon: fill 7 9 17 9 17 20 7 20 line 12 14 12 3 line 4 8 4 21 line 20 8 20 21
state px = 4;                   // my tank: its square and the way it faces
state py = 8;
state pdx = 0;
state pdy = -1;
state ex = 4;                   // the computer's tank
state ey = 0;
state hx = [0, 0];              // the shells, mine (0) and the computer's (1)
state hy = [0, 0];
state hdx = [0, 0];
state hdy = [0, 0];
state hon = [false, false];
state me = 0;
state cpu = 0;
state steps = 0;                // steps since the round began
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn wall(c: int, r: int) -> bool {
  return (c == 2 || c == 6) && (r == 2 || r == 6) || c == 4 && r == 4;
}

fn open(c: int, r: int) -> bool {
  return c >= 0 && c < 9 && r >= 0 && r < 9 && !wall(c, r);
}

fn sign(n: int) -> int { return max(-1, min(1, n)); }

// Both tanks back where they start, no shell flying.
fn round() {
  px = 4;
  py = 8;
  pdx = 0;
  pdy = -1;
  ex = 4;
  ey = 0;
  hon = [false, false];
  steps = 0;
}

fn start() {
  me = 0;
  cpu = 0;
  result = "";
  round();
  speed = 100;
}

// A hit for side k (0 me, 1 the computer): 3 wins, else a new round.
fn scored(k: int) {
  if k == 0 { me += 1; } else { cpu += 1; }
  if me == 3 {
    result = "You win";
    speed = 0;
  } else if cpu == 3 {
    result = "You lose";
    speed = 0;
  } else {
    round();
  }
}

// Shell k on the other tank's square hits it.
fn strike(k: int) {
  let c = ex;
  let r = ey;
  if k == 1 {
    c = px;
    r = py;
  }
  if hon[k] && hx[k] == c && hy[k] == r {
    hon[k] = false;
    scored(k);
  }
}

// Shell k on a wall or off the board is gone; on the other tank it hits.
fn land(k: int) {
  if !open(hx[k], hy[k]) { hon[k] = false; }
  strike(k);
}

fn fly(k: int) {
  if hon[k] {
    hx[k] += hdx[k];
    hy[k] += hdy[k];
    land(k);
  }
}

fn shoot(k: int, c: int, r: int, dx: int, dy: int) {
  if speed > 0 && !hon[k] {
    hx[k] = c + dx;
    hy[k] = r + dy;
    hdx[k] = dx;
    hdy[k] = dy;
    hon[k] = true;
    land(k);
  }
}

fn drive(dx: int, dy: int) {
  if speed == 0 { return; }
  pdx = dx;
  pdy = dy;
  if open(px + dx, py + dy) && !(px + dx == ex && py + dy == ey) {
    px += dx;
    py += dy;
    strike(1);
  }
}

// Whether the computer sees me: in my column or row, no wall between.
fn sight() -> bool {
  if ex != px && ey != py { return false; }
  let c = ex;
  let r = ey;
  for i in 0..9 {
    c += sign(px - ex);
    r += sign(py - ey);
    if c == px && r == py { return true; }
    if wall(c, r) { return false; }
  }
  return true;
}

fn free(c: int, r: int) -> bool { return open(c, r) && !(c == px && r == py); }

// The computer's turn: fire if it sees me, else close in, across first.
fn think() {
  let dx = sign(px - ex);
  let dy = sign(py - ey);
  if sight() {
    shoot(1, ex, ey, dx, dy);
  } else if dx != 0 && free(ex + dx, ey) {
    ex += dx;
    strike(0);
  } else if dy != 0 && free(ex, ey + dy) {
    ey += dy;
    strike(0);
  }
}

// A step: my shell, then the computer's, then every 3rd step the computer; a hit ends the step.
every speed {
  steps += 1;
  fly(0);
  if speed > 0 && steps > 0 { fly(1); }
  if speed > 0 && steps > 0 && steps % 3 == 0 { think(); }
}

on key "left" { drive(-1, 0); }
on key "right" { drive(1, 0); }
on key "up" { drive(0, -1); }
on key "down" { drive(0, 1); }
on key "space" { shoot(0, px, py, pdx, pdy); }

fn scene() {
  let cells = [-1; 81];
  for i in 0..81 {
    if wall(i % 9, i / 9) { cells[i] = 8; }
  }
  for k in 0..2 {
    if hon[k] { cells[hy[k] * 9 + hx[k]] = 3; }
  }
  cells[py * 9 + px] = 4;
  cells[ey * 9 + ex] = 1;
  pixels(cells, 0, 0, 9, 10);
  if result != "" { text(result, 45, 30, 14, 11); }
}

