// Tank Battle for two: blue drives with w a s d and fires with space, red with the arrows and
// enter. Shells break purple bricks; gray steel stops them. Three hits and a tank is out.
// icon: fill 3 8 11 8 11 16 3 16 line 11 12 15 12 fill 13 8 21 8 21 16 13 16
state tx = [0, 10];             // the tanks, blue (0) and red (1): square and facing
state ty = [3, 3];
state fx = [1, -1];
state fy = [0, 0];
state armor = [3, 3];
state sx = [0, 0];              // their shells, each flying or not
state sy = [0, 0];
state sdx = [0, 0];
state sdy = [0, 0];
state son = [false, false];
state bricks = [false; 77];     // the bricks still standing
state speed = 0;                // ms a step; 0 while no game runs
state result = "";

fn at(c: int, r: int) -> int { return r * 11 + c; }

fn steel(c: int, r: int) -> bool { return c == 5 && (r < 2 || r > 4); }

fn start() {
  for i in 0..77 { bricks[i] = false; }
  for r in 2..5 { bricks[at(5, r)] = true; }
  bricks[at(3, 3)] = true;
  bricks[at(7, 3)] = true;
  tx = [0, 10];
  ty = [3, 3];
  fx = [1, -1];
  fy = [0, 0];
  armor = [3, 3];
  son = [false, false];
  result = "";
  speed = 100;
}

fn inside(c: int, r: int) -> bool { return c >= 0 && c < 11 && r >= 0 && r < 7; }

// Shell k meets what is on its square: the edge or steel ends it, a brick breaks with it, the
// other tank loses one armor.
fn meet(k: int) {
  let c = sx[k];
  let r = sy[k];
  if !inside(c, r) || steel(c, r) {
    son[k] = false;
  } else if bricks[at(c, r)] {
    bricks[at(c, r)] = false;
    son[k] = false;
  } else if c == tx[1 - k] && r == ty[1 - k] {
    son[k] = false;
    armor[1 - k] -= 1;
    if armor[1 - k] == 0 {
      result = "Blue wins";
      if k == 1 { result = "Red wins"; }
      speed = 0;
    }
  }
}

fn fire(k: int) {
  if speed > 0 && !son[k] {
    sx[k] = tx[k] + fx[k];
    sy[k] = ty[k] + fy[k];
    sdx[k] = fx[k];
    sdy[k] = fy[k];
    son[k] = true;
    meet(k);
  }
}

// Tank k turns that way and moves a square unless the edge, a wall or the other tank is there.
fn drive(k: int, dx: int, dy: int) {
  if speed == 0 { return; }
  fx[k] = dx;
  fy[k] = dy;
  let c = tx[k] + dx;
  let r = ty[k] + dy;
  if inside(c, r) && !steel(c, r) && !bricks[at(c, r)] && !(c == tx[1 - k] && r == ty[1 - k]) {
    tx[k] = c;
    ty[k] = r;
    let o = 1 - k;
    if son[o] && sx[o] == c && sy[o] == r { meet(o); }
  }
}

every speed {
  for k in 0..2 {
    if speed > 0 && son[k] {
      sx[k] += sdx[k];
      sy[k] += sdy[k];
      meet(k);
    }
  }
}

