}

fn dig(dx: int, dy: int) {
  let c = px + dx;
  let r = py + dy;
  if speed > 0 && c >= 0 && c < 9 && r >= 0 && r < 10 && !rock(c, r) {
    px = c;
    py = r;
    dirt[at(c, r)] = false;
    if monster(c, r) >= 0 { caught(); }
  }
}

