// monster ahead; three pumps pop it. Two levels, faster monsters on the second, and 3 lives.
// icon: fill 3 9 21 9 21 21 3 21 dot 9 15 3 line 12 15 19 15 ring 12 5 3
state dirt = [false; 81];       // dirt on each square, or dug
