fn at(c: int, r: int) -> int { return r * 9 + c; }

fn inside(c: int, r: int) -> bool { return c >= 0 && c < 9 && r >= 0 && r < 9; }

// The tunnels each level begins with: row 3 at columns 1 to 5, row 6 at columns 3 to 7.
fn tunnel(c: int, r: int) -> bool {
  return r == 3 && c >= 1 && c <= 5 || r == 6 && c >= 3 && c <= 7;
}

fn monster(c: int, r: int) -> int {
  for i in 0..2 {
    if alive[i] && mx[i] == c && my[i] == r { return i; }
