  home();
  if lives == 0 {
    result = "Game over";
    speed = 0;
  }
}

fn free(c: int, r: int) -> bool { return inside(c, r) && !dirt[at(c, r)] && monster(c, r) < 0; }

fn sign(n: int) -> int { return max(-1, min(1, n)); }

// Monster i's turn: a pumped one loses a pump, else it moves toward the digger, across first.
fn hunt(i: int) -> bool {
  if pumps[i] > 0 {
    pumps[i] -= 1;
    return false;
  }
  let dx = sign(px - mx[i]);
  let dy = sign(py - my[i]);
  if dx != 0 && (mx[i] + dx == px && my[i] == py || free(mx[i] + dx, my[i])) {
    mx[i] += dx;
  } else if dy != 0 && (mx[i] == px && my[i] + dy == py || free(mx[i], my[i] + dy)) {
    my[i] += dy;
  }
  return mx[i] == px && my[i] == py;
}

every speed {
