  if over != "" { button "New game" { reset(); } }
}

// Star trader: tap a planet to fly there (fuel and days by distance); buy ore and spice where
// they are cheap and sell where they are dear. Reach 150 credits by Day 30.
// icon: ring 12 12 5 line 2 15 22 9 dot 19 5 2
state names = ["Terra", "Mars", "Vega", "Zed"];
state px = [0, 5, 2, 5];       // the planets' columns and rows on the 6 x 4 map
state py = [0, 0, 3, 3];
state tint = [4, 1, 3, 5];
state ore = [10, 4, 8, 14];    // each planet's price of ore, and of spice
state spice = [4, 12, 6, 9];
state at = 0;
state credits = 30;
state fuel = 10;
state day = 1;
state hold = [0, 0];           // ore and spice aboard
state over = "";               // You win or Game over, once it ends

// The planet on map square i, or -1.
fn planet(i: int) -> int {
  for k in 0..4 {
    if py[k] * 6 + px[k] == i { return k; }
  }
  return -1;
}

fn price(g: int) -> int {
  if g == 0 { return ore[at]; }
  return spice[at];
}

fn buy(g: int) {
  if over == "" && credits >= price(g) && hold[0] + hold[1] < 10 {
    credits -= price(g);
    hold[g] += 1;
  }
}

fn sell(g: int) {
  if over == "" && hold[g] > 0 {
    hold[g] -= 1;
    credits += price(g);
    if credits >= 150 { over = "You win"; }
  }
}

fn refuel() {
  if over == "" && credits >= 2 && fuel < 20 {
    credits -= 2;
    fuel += 1;
  }
}

fn fly(i: int) {
  let k = planet(i);
  if over != "" || k < 0 || k == at { return; }
  let d = abs(px[k] - px[at]) + abs(py[k] - py[at]);
  if d > fuel { return; }
  fuel -= d;
  day += d;
  at = k;
  if day > 30 { over = "Game over"; }
}

fn reset() {
  at = 0;
  credits = 30;
  fuel = 10;
  day = 1;
  hold[0] = 0;
  hold[1] = 0;
  over = "";
}

// The map, 6 x 4 squares of 20 units: each planet in its color, the one you are at green.
fn scene() {
  rect(0, 0, 120, 80, 9);
  for k in 0..4 {
    let c = tint[k];
    if k == at { c = 2; }
    circle(px[k] * 20 + 10, py[k] * 20 + 10, 8, c);
  }
  if over != "" { text(over, 60, 40, 14, 11); }
}

label "Star trader";
