// Castaway: the arrows (or a tap beside you) walk, chop trees for wood and eat berries; every
// action makes you hungrier. Build a raft from 5 wood and sail off before Hunger reaches 15.
// icon: loop 3 15 21 15 18 20 6 20 line 12 15 12 3 fill 12 4 19 12 12 12
state first = [4, 4, 4, 4, 4, 4, 4, 4,  4, 3, 2, 3, 3, 8, 2, 4,  4, 3, 3, 5, 3, 2, 3, 4,
               4, 2, 8, 3, 3, 3, 5, 4,  4, 3, 2, 3, 8, 2, 3, 4,  4, 4, 4, 4, 4, 4, 4, 4];
state map = [4, 4, 4, 4, 4, 4, 4, 4,  4, 3, 2, 3, 3, 8, 2, 4,  4, 3, 3, 5, 3, 2, 3, 4,
             4, 2, 8, 3, 3, 3, 5, 4,  4, 3, 2, 3, 8, 2, 3, 4,  4, 4, 4, 4, 4, 4, 4, 4];
// 8 x 6 squares, row by row, by color: 4 water, 3 sand, 2 tree, 8 rock, 5 berry bush
state px = 1;
state py = 1;
state wood = 0;
state hunger = 0;
state raft = false;
state over = "";             // Escaped or Game over, once it ends

// A step toward (dx, dy): walk, chop or eat; rocks and water (without a raft) stop you.
fn step(dx: int, dy: int) {
  if over != "" { return; }
  let i = (py + dy) * 8 + px + dx;
  let t = map[i];
  if t == 8 { return; }
  if t == 4 {
    if raft { over = "Escaped"; }
    return;
  }
  hunger += 1;
  if t == 2 {
    wood += 1;
    map[i] = 3;
  } else if t == 5 {
    hunger = max(0, hunger - 8);
    map[i] = 3;
  } else {
    px += dx;
    py += dy;
  }
  if hunger >= 15 { over = "Game over"; }
}

fn toward(c: int, r: int) {
  if abs(c - px) + abs(r - py) == 1 { step(c - px, r - py); }
}

fn build() {
  if over == "" && !raft && wood >= 5 {
    wood -= 5;
    raft = true;
  }
}

fn reset() {
  for i in 0..48 { map[i] = first[i]; }
  px = 1;
  py = 1;
  wood = 0;
  hunger = 0;
  raft = false;
  over = "";
}

// The map, 8 x 6 squares of 16 units, you in red.
fn scene() {
  let cells = [0; 48];
  for i in 0..48 { cells[i] = map[i]; }
  cells[py * 8 + px] = 1;
  pixels(cells, 0, 0, 8, 16);
  if over != "" { text(over, 64, 48, 14, 9); }
}

on key "left" { step(-1, 0); }
on key "right" { step(1, 0); }
on key "up" { step(0, -1); }
on key "down" { step(0, 1); }

label "Castaway";
label "Wood " + wood + "   Hunger " + hunger;
if raft { label "Raft ready"; }
canvas 128, 96, scene() {
  if x < 128 && y < 96 { toward(x / 16, y / 16); }
}
row {
  button "Build raft" { build(); }
  if over != "" { button "New game" { reset(); } }
}

// Island rescue: Start the clock; Chop wood, Fish and Eat, Sleep at night, Light a signal fire
// so it burns when the ship passes at noon. Hunger 20 ends it.
// icon: line 4 20 20 20 line 12 20 12 6 fill 12 6 19 9 12 12 fill 6 18 12 13 18 18
state day = 1;
state hour = 6;
state hunger = 0;
state energy = 10;
state wood = 0;
state fish = 0;
state fire = 0;              // the hours the fire has left
state speed = 0;             // ms an hour: 1000 while the clock runs
state begun = false;
state over = "";             // Rescued or Game over, once it ends

fn night() -> bool { return hour >= 20 || hour <= 5; }

fn awake() -> bool { return speed > 0; }

fn starve() {
  if hunger >= 20 {
    over = "Game over";
    speed = 0;
  }
}

fn work(n: int) -> bool {
  if !awake() || energy < n { return false; }
  energy -= n;
  return true;
}

fn eat() {
  if awake() && fish > 0 {
    fish -= 1;
    hunger = max(0, hunger - 6);
  }
}

fn light() {
  if awake() && wood >= 5 {
    wood -= 5;
    fire = 4;
  }
}

// Asleep until hour 6: rested, hungrier, the fire lower by the hours slept.
fn sleep() {
  if !awake() || !night() { return; }
  let n = (30 - hour) % 24;
  if hour >= 20 { day += 1; }
  hour = 6;
  energy = 10;
  hunger += n;
  fire = max(0, fire - n);
  starve();
}

fn reset() {
  day = 1;
  hour = 6;
  hunger = 0;
  energy = 10;
  wood = 0;
  fish = 0;
  fire = 0;
  speed = 0;
  begun = false;
  over = "";
}

every speed {
  hour += 1;
  if hour == 24 {
    hour = 0;
    day += 1;
  }
  hunger += 1;
  fire = max(0, fire - 1);
  if hour == 12 && fire > 0 {
    over = "Rescued";
    speed = 0;
  } else {
    starve();
  }
}

// The island under a day or night sky, a palm, and the fire while it burns.
fn scene() {
  let sky = 6;
  if night() { sky = 9; }
  rect(0, 0, 160, 70, sky);
  rect(0, 70, 160, 30, 4);
  circle(80, 90, 50, 3);
  line(60, 70, 64, 40, 3, 8);
  circle(64, 40, 8, 2);
  if fire > 0 {
    circle(100, 60, 6, 1);
    circle(100, 54, 3, 3);
  }
  if over != "" { text(over, 80, 20, 14, 11); }
}

label "Island rescue";
label "Day " + day + "   Hour " + hour + "   Hunger " + hunger + "   Energy " + energy;
label "Wood " + wood + "   Fish " + fish + "   Fire " + fire;
canvas 160, 100, scene();
row {
  button "Chop" {
    if work(2) { wood += 3; }
  }
  button "Fish" {
    if work(2) { fish += 1; }
  }
  button "Eat" { eat(); }
  button "Light fire" { light(); }
  button "Sleep" { sleep(); }
}
if !begun {
  button "Start" {
    begun = true;
    speed = 1000;
  }
}
if over != "" { button "New game" { reset(); } }
